Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
smb: client: require a full NFS mode SID before reading mode
 bits

parse_dacl() treats an ACE SID matching sid_unix_NFS_mode as an NFS
mode SID and reads sid.sub_auth[2] to recover the mode bits.

That assumes the ACE carries three subauthorities, but compare_sids()
only compares min(a, b) subauthorities.  A malicious server can return
an ACE with num_subauth = 2 and sub_auth[] = {88, 3}, which still
matches sid_unix_NFS_mode and then drives the sub_auth[2] read four
bytes past the end of the ACE.

Require num_subauth >= 3 before treating the ACE as an NFS mode SID.
This keeps the fix local to the special-SID mode path without changing
compare_sids() semantics for the rest of cifsacl.

Fixes: e2f8fbfb8d09 ("cifs: get mode bits from special sid on stat")
Cc: stable@vger.kernel.org
Assisted-by: Claude:claude-opus-4-6
Signed-off-by: Michael Bommarito <michael.bommarito@gmail.com>
Signed-off-by: Steve French <stfrench@microsoft.com>

Here is the root cause:
In parse_dacl() in cifsacl.c, the code does not check that the ACE's SID has at least 3 subauthorities before treating it as an NFS mode SID. The compare_sids() function only compares up to the smaller number of subauthorities, so an ACE with 2 subauthorities that matches sid_unix_NFS_mode's first two subauthorities is considered equal, leading to an out-of-bounds read when accessing sub_auth[2].

Here is the patch:

 static void parse_dacl(struct smb_acl *pdacl, char *end_of_acl,
 		       struct smb_sid *pownersid, struct smb_sid *pgrpsid,
 		       struct cifs_fattr *fattr, bool mode_from_special_sid)
 {
 	int i;
 	u16 num_aces = 0;
 	int acl_size;
 	char *acl_base, *end_of_dacl;
 	struct smb_ace **ppace;

 	/* BB need to add parm so we can store the SID BB */

 	if (!pdacl) {
 		/* no DACL in the security descriptor, set
 		   all the permissions for user/group/other */
 		fattr->cf_mode |= 0777;
 		return;
 	}

 	if (validate_dacl(pdacl, end_of_acl))
 		return;

 	cifs_dbg(NOISY, "DACL revision %d size %d num aces %d\n",
 		 le16_to_cpu(pdacl->revision), le16_to_cpu(pdacl->size),
 		 le16_to_cpu(pdacl->num_aces));

 	/* reset rwx permissions for user/group/other.
 	   Also, if num_aces is 0 i.e. DACL has no ACEs,
 	   user/group/other have no permissions */
 	fattr->cf_mode &= ~(0777);

 	end_of_dacl = (char *)pdacl + le16_to_cpu(pdacl->size);
 	acl_base = (char *)pdacl;
 	acl_size = sizeof(struct smb_acl);

 	num_aces = le16_to_cpu(pdacl->num_aces);
 	if (num_aces > 0) {
 		umode_t denied_mode = 0;

 		ppace = kmalloc_objs(struct smb_ace *, num_aces);
 		if (!ppace)
 			return;

 		for (i = 0; i < num_aces; ++i) {
 			ppace[i] = (struct smb_ace *) (acl_base + acl_size);

 #ifdef CONFIG_CIFS_DEBUG2
 			dump_ace(ppace[i], end_of_dacl);
 #endif
 			if (mode_from_special_sid &&
+			    ppace[i]->sid.num_subauth >= 3 &&
 			    (compare_sids(&(ppace[i]->sid),
 					  &sid_unix_NFS_mode) == 0)) {
 				/*
 				 * Full permissions are:
 				 * 07777 = S_ISUID | S_ISGID | S_ISVTX |
 				 *         S_IRWXU | S_IRWXG | S_IRWXO
 				 */
 				fattr->cf_mode &= ~07777;
 				fattr->cf_mode |=
 					le32_to_cpu(ppace[i]->sid.sub_auth[2]);
 				break;
 			} else {
 				if (compare_sids(&(ppace[i]->sid), pownersid) == 0) {
 					access_flags_to_mode(ppace[i]->access_req,
 							ppace[i]->type,
 							&fattr->cf_mode,
 							&denied_mode,
 							ACL_OWNER_MASK);
 				} else if (compare_sids(&(ppace[i]->sid), pgrpsid) == 0) {
 					access_flags_to_mode(ppace[i]->access_req,
 							ppace[i]->type,
 							&fattr->cf_mode,
 							&denied_mode,
 							ACL_GROUP_MASK);
 				} else if ((compare_sids(&(ppace[i]->sid), &sid_everyone) == 0) ||
 						(compare_sids(&(ppace[i]->sid), &sid_authusers) == 0)) {
 					access_flags_to_mode(ppace[i]->access_req,
 							ppace[i]->type,
 							&fattr->cf_mode,
 							&denied_mode,
 							ACL_EVERYONE_MASK);
 				}
 			}


 /*			memcpy((void *)(&(cifscred->aces[i])),
 				(void *)ppace[i],
 				sizeof(struct smb_ace)); */

 			acl_base = (char *)ppace[i];
 			acl_size = le16_to_cpu(ppace[i]->size);
 		}

 		kfree(ppace);
 	}

 	return;
 }



